#include <map>
#include <utility>

struct StatefulComparator {
    int state = 0;
    bool operator()(int a, int b) const { return a < b; }
    // If copy assignment throws, map::swap might throw.
    // To guarantee no-throw swap, this should be noexcept.
    void swap(StatefulComparator& other) noexcept {
        std::swap(state, other.state);
    }
};

int main() {
    // Map using a custom, stateful comparator.
    std::map<int, double, StatefulComparator> m1;
    std::map<int, double, StatefulComparator> m2;

    // The exception safety of this swap depends entirely 
    // on the exception safety of StatefulComparator's swap/assignment.
    m1.swap(m2);

    return 0;
}
